-- Marketing Studio gets two more models with native audio, as the reference site makes every marketing clip with sound. Seedance 2.0 and 2.5
-- reference-to-video take a list of images the prompt names @Image1, @Image2 (like Kling O3 Pro), have generate_audio, and price by resolution
-- and tokens only, so audio costs nothing more (fal model pages and input schemas, read 2026-10-26). They also accept 16:9, and 9 (2.0) and 30 (2.5)
-- reference images, so both take Marketing Studio Advanced's 7. Create Video keeps its own 4-image limit and its 9:16 and 1:1 (the jobs and models APIs).
UPDATE "model_configs" SET "features" = array_append("features", 'marketing'), "ratios" = ARRAY['9:16', '1:1', '16:9']::text[], "max_images" = 7, "sources" = "sources" || jsonb_build_object('ratios', jsonb_build_object('url', 'https://fal.ai/api/openapi/queue/openapi.json?endpoint_id=' || "endpoint", 'readAt', '2026-10-26'), 'maxImages', jsonb_build_object('url', 'https://fal.ai/api/openapi/queue/openapi.json?endpoint_id=' || "endpoint", 'readAt', '2026-10-26', 'note', 'the app takes up to 7, Marketing Studio Advanced''s limit')), "updated_at" = now() WHERE "id" IN ('seedance-2.0-reference', 'seedance-2.5-reference') AND NOT 'marketing' = ANY("features");
